INSERT INTO mod_wording (row_id, unique_row, old_key, new_key, fields, en, note)
VALUES
  (42, true, '42|||ייעוץ פסיכיאטרי מקוון', '42|||טיפול פסיכיאטרי: הערכה ומעקב. בשיחת וידאו.', '{"specialty":"","approaches":"","svc":"טיפול פסיכיאטרי: הערכה ומעקב. בשיחת וידאו.","meeting":"","target":"חיילים וחיילות משוחררים, באישור אגף השיקום","region":"","cost":"ללא עלות","notes":"ההפניה נשלחת ל-rigshi@md-trix.com.","phone":"03-7545938","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"rigshi@md-trix.com","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"specialty":"","approaches":"","org":"Sharan","svc":"Psychiatric treatment: assessment and follow-up. In a video call.","meeting":"","target":"Discharged soldiers, with approval from the rehabilitation division","region":"","cost":"At no cost","notes":"The referral is sent to rigshi@md-trix.com.","phone":"03-7545938","phoneLabel":"Call center","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"rigshi@md-trix.com","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '25.11.2026: נבדק מול https://sharanmedical.co.il/online-psychiatric-consultation-for-idf/. שעות המוקד ומספרי המשרד הכלליים לא עולים לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (214, true, '214|||סיוע נפשי לחיילים ומילואים', '214|||פסיכותרפיה אחרי לחימה או פעילות מבצעית. ביחידה.', '{"specialty":"","approaches":"טיפול פרטני, טיפול זוגי, טיפול קבוצתי, טיפול ממוקד טראומה","org":"היחידה לתגובות קרב","svc":"פסיכותרפיה אחרי לחימה או פעילות מבצעית. ביחידה.","meeting":"in_person","target":"חיילים משוחררים מסדיר ומילואים","region":"פתח תקווה","cost":"ללא עלות","notes":"אפעל 6. אין צורך בהכרה בנכות, ואין מגבלת זמן מאז האירוע.","web":"https://shikum.mod.gov.il/ContactUs/CombatResponse","phone":"03-6401400","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"specialty":"","approaches":"Individual therapy, couples therapy, group therapy, trauma-focused therapy","org":"The Combat Response Unit","svc":"Psychotherapy after combat or operational activity. At the unit.","meeting":"in_person","target":"Discharged regular and reserve soldiers","region":"Petah Tikva","cost":"At no cost","notes":"6 Efal St. No disability recognition is required, and there is no time limit since the event.","phone":"03-6401400","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/ContactUs/CombatResponse. העמוד אינו מציין טיפול תרופתי. השעות לא עולות לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (218, true, '218|||טיפולים נפשיים מסובסדים ע"י משרד הביטחון (חרבות ברזל)', '218|||פסיכותרפיה במימון אגף השיקום.', '{"specialty":"","approaches":"טיפול פרטני, טיפול זוגי, טיפול משפחתי, טיפול קבוצתי","org":"אגף השיקום, משרד הבטחון","svc":"פסיכותרפיה במימון אגף השיקום.","meeting":"","target":"מי שהוכר, או מי שאושר לו טיפול רפואי בזמן ההכרה","region":"כל הארץ","cost":"אגף השיקום","notes":"פונים לעובדת השיקום. נפגעי חרבות ברזל יכולים לקבל טיפול גם אם הבקשה היא על פגיעה פיזית בלבד. מי שהוכר רטרואקטיבית יכול לבקש החזר על טיפולים מלפני הבקשה. טיפול בחו״ל אפשרי בפגיעה נפשית או בפגיעת ראש."}'::jsonb, '{"specialty":"","approaches":"Individual therapy, couples therapy, family therapy, group therapy","org":"Rehabilitation Division, Ministry of Defense","svc":"Psychotherapy funded by the rehabilitation division.","meeting":"","target":"A person who was recognized, or a person approved for medical treatment during recognition","region":"Nationwide","cost":"The rehabilitation division","notes":"Apply to the rehabilitation social worker. Iron Swords casualties can receive treatment even when the claim is for a physical injury only. A person recognized retroactively can ask for a refund of treatments from before the claim. Treatment abroad is possible for a mental injury or a head injury."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/medical/treatment/therapy. זה דף הפסיכותרפיה הכללי, לא רק חרבות ברזל. הניסוח אושר עם אצוות משרד הביטחון.'),
  (223, true, '223|||סיוע מקצועי לנפגעים בצה"ל ולבני משפחותיהם', '223|||מידע, ליווי וסיוע בהגשת בקשה להכרה, לנפגעי השירות ולבני משפחותיהם.', '{"specialty":"","approaches":"","org":"קשר עד","svc":"מידע, ליווי וסיוע בהגשת בקשה להכרה, לנפגעי השירות ולבני משפחותיהם.","meeting":"","target":"נפגעי השירות ובני משפחותיהם","region":"כל הארץ","cost":"ללא עלות","notes":"","web":"https://www.miluim.idf.il/articles-list/%D7%A4%D7%92%D7%99%D7%A2%D7%94-%D7%91%D7%9E%D7%94%D7%9C%D7%9A-%D7%A9%D7%99%D7%A8%D7%95%D7%AA-%D7%9E%D7%99%D7%9C%D7%95%D7%90%D7%99%D7%9D","phone":"1111","phoneLabel":"שלוחה 6","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"specialty":"","approaches":"","org":"Kesher Ad","svc":"Information, accompaniment, and help filing a recognition request, for service casualties and their family members.","meeting":"","target":"Service casualties and their family members","region":"Nationwide","cost":"At no cost","notes":"","phone":"1111","phoneLabel":"Extension 6","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול https://www.miluim.idf.il/articles-list/%D7%A4%D7%92%D7%99%D7%A2%D7%94-%D7%91%D7%9E%D7%94%D7%9C%D7%9A-%D7%A9%D7%99%D7%A8%D7%95%D7%AA-%D7%9E%D7%99%D7%9C%D7%95%D7%90%D7%99%D7%9D. *6690 הוא מוקד אחר. העמוד מציין 1111 שלוחה 6. הניסוח אושר עם אצוות משרד הביטחון.'),
  (225, true, '225|||טיפול נפשי ללוחמי גזית/שריון (חטיבה 188) — ללא תשלום', '225|||טיפול נפשי לחיילי שריון ולמפקדים, לשנה, ללא תשלום.', '{"specialty":"","approaches":"","svc":"טיפול נפשי לחיילי שריון ולמפקדים, לשנה, ללא תשלום.","meeting":"","target":"חיילי שריון ומפקדים, בסדיר ובמילואים","region":"","cost":"ללא עלות","notes":"לזכר סרן יהל גזית. הטיפול בתיאום עם מערך בריאות הנפש. מי שמתמודד עם פוסט טראומה, אובדנות או מצב קיצון ממשיך לקבל סיוע מהקב״ן. ההרשמה באתר.","web":"https://barak-188.com/%D7%9E%D7%99%D7%96%D7%9D-%D7%90%D7%95%D7%A8-%D7%9B%D7%99-%D7%99%D7%94%D7%9C/","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"specialty":"","approaches":"","org":"Or Ki Yahel","svc":"Mental-health treatment for armor soldiers and commanders, for a year, at no charge.","meeting":"","target":"Armor soldiers and commanders, in regular service and in the reserves","region":"","cost":"At no cost","notes":"In memory of Captain Yahel Gazit. The treatment is coordinated with the IDF mental-health array. A person coping with post-traumatic stress, suicidality, or an extreme state continues to receive help from the combat mental-health officer. Registration is on the site.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול https://barak-188.com/%D7%9E%D7%99%D7%96%D7%9D-%D7%90%D7%95%D7%A8-%D7%9B%D7%99-%D7%99%D7%94%D7%9C/. הטלפון של מיה גזית אינו בעמוד המיזם. הניסוח אושר עם אצוות משרד הביטחון.'),
  (281, true, '281|||שיקום לנכי צה"ל ונפגעי פעולות איבה — מרכז החממה ותכנית תושייה למשפחות הלומי קרב', '281|||שיקום תעסוקתי לנכי צה״ל ולנפגעי פעולות איבה, וקבוצות תמיכה למשפחות הלומי קרב. במרכז.', '{"specialty":"","approaches":"","svc":"שיקום תעסוקתי לנכי צה״ל ולנפגעי פעולות איבה, וקבוצות תמיכה למשפחות הלומי קרב. במרכז.","meeting":"in_person","target":"נכי צה״ל, נפגעי פעולות איבה, ובני משפחות של הלומי קרב","region":"ירושלים, אשקלון","cost":"","notes":"החממה היא מרכז לפיתוח תעסוקה. תושייה היא קבוצות להורים, לבנות זוג, לילדים ולאחים.","phone":"02-5656900","phoneLabel":"משרד","phoneShowNumber":false,"phone2":"077-900-2283","phoneLabel2":"מוקד","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"specialty":"","approaches":"","org":"The Association for Public Health","svc":"Vocational rehabilitation for IDF disabled people and for victims of hostilities, and support groups for families of people with combat post-traumatic stress. At the center.","meeting":"in_person","target":"IDF disabled people, victims of hostilities, and family members of people with combat post-traumatic stress","region":"Jerusalem, Ashkelon","cost":"","notes":"HaHamama is a center for developing employment. Tushiya is groups for parents, partners, children, and siblings.","phone":"02-5656900","phoneLabel":"Office","phone2":"077-900-2283","phoneLabel2":"Call center","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול עמוד הקטגוריה באתר האגודה לבריאות הציבור. הכתובת ברחובות אינה בעמוד הזה. השעות לא עולות לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (756, true, '756|||טיפולים, ספורט וסדנאות בחינם למשוחררי מלחמת חרבות ברזל', '756|||טיפול נפשי, ספורט, רפואה משלימה וסדנאות למשוחררי מלחמת חרבות ברזל.', '{"specialty":"","approaches":"","svc":"טיפול נפשי, ספורט, רפואה משלימה וסדנאות למשוחררי מלחמת חרבות ברזל.","meeting":"","target":"משוחררי סדיר ומילואים לפי תנאי התוכנית, מ-7.10.2023","region":"כל הארץ","cost":"ללא עלות","notes":"12 מפגשי טיפול נפשי, פרטניים או זוגיים, עד 31.12.2027. מצטרפים באפליקציה. עד 31.12.2025: מילואים מעל 30 יום, או סדיר שהשתחרר. מ-1.1.2026: מילואים לוחמים של 50 יום, או סדיר עם תעודת שחרור בכבוד, זהב או כסף, וגם מסלול לקבע. מי שגר בחו״ל יכול לקבל את הטיפול הנפשי מרחוק."}'::jsonb, '{"specialty":"","approaches":"","org":"Amit program (Ministry of Defense)","svc":"Mental-health treatment, sport, complementary medicine, and workshops for people discharged after the Iron Swords war.","meeting":"","target":"Discharged regular and reserve soldiers under the program conditions, from 7.10.2023","region":"Nationwide","cost":"At no cost","notes":"12 mental-health sessions, individual or couples, through 31.12.2027. People join in the app. Through 31.12.2025: reserves of more than 30 days, or a regular soldier who was discharged. From 1.1.2026: combat reserves of 50 days, or regular service with an honorable, gold, or silver discharge certificate, and also a path for career soldiers. A person who lives abroad can receive the mental-health treatment remotely."}'::jsonb, '25.11.2026: נבדק מול https://tochnitamit.mod.gov.il/. ההערה על מי שכבר הוכר אינה בדף הבית. הניסוח אושר עם אצוות משרד הביטחון.'),
  (759, true, '759|||כלב סיוע להתמודדות עם פוסט טראומה', '759|||כלב סיוע להתמודדות עם פוסט טראומה.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"כלב סיוע להתמודדות עם פוסט טראומה.","meeting":"","target":"מי שהוכר בגלל פוסט טראומה, עם 20% נכות לפחות, או 10% אם ההכרה עד 31.12.1995","region":"כל הארץ","cost":"אגף השיקום","notes":"הכלב מזהה עלייה בחרדה, מסייע בהתקף ומעיר מסיוט. הוא נשאר בבעלות הספק. פונים למחלקת השיקום במחוז. אחרי קבלה יש תשלום חודשי להוצאות הכלב. אין החזר על כלב שנרכש באופן עצמאי."}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"A service dog for coping with post-traumatic stress.","meeting":"","target":"A person recognized for post-traumatic stress, with at least 20% disability, or 10% if the recognition is through 31.12.1995","region":"Nationwide","cost":"The rehabilitation division","notes":"The dog identifies rising anxiety, helps during an attack, and wakes the person from a nightmare. The dog remains owned by the supplier. Apply through the district rehabilitation department. After acceptance there is a monthly payment for the cost of keeping the dog. There is no refund for a dog bought privately."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/medical/hospitalization/service-dog. 396 ש״ח לא עולה לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (760, true, '760|||חוות שיקומיות לפוסט טראומה', '760|||שיקום בחווה למי שמתמודד עם תסמיני פוסט טראומה. בחווה.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"שיקום בחווה למי שמתמודד עם תסמיני פוסט טראומה. בחווה.","meeting":"in_person","target":"מי שהוכר על מצב נפשי, או מי שאובחן עם תסמיני פוסט טראומה ועדיין לא השלים הכרה","region":"כרמיאל, רמת גן, סתריה, נתיב הל״ה, תל מונד, צור הדסה, בית שמש, עין יעל, ירושלים, להב","cost":"אגף השיקום","notes":"עד 6 חודשים, מהבוקר עד אחר הצהריים. ההצטרפות דרך עובדת השיקום. רטורנו בכרטיס נפרד."}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Rehabilitation on a farm for a person coping with post-traumatic symptoms. On the farm.","meeting":"in_person","target":"A person recognized for a mental condition, or a person diagnosed with post-traumatic symptoms who has not finished recognition","region":"Karmiel, Ramat Gan, Sitria, Netiv HaLamed-Heh, Tel Mond, Tzur Hadassah, Beit Shemesh, Ein Yael, Jerusalem, Lahav","cost":"The rehabilitation division","notes":"Up to 6 months, from morning to afternoon. Joining is through the rehabilitation social worker. Retorno is on a separate card."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/rehabilitation/vocational/farms-therapy. ימי הפעילות לא עולים לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (761, true, '761|||בית מעבר בית מעגן', '761|||פסיכותרפיה, וגם טיפול פסיכיאטרי, בבית מעבר לפוסט טראומה. בשהייה בבית.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"פסיכותרפיה, וגם טיפול פסיכיאטרי, בבית מעבר לפוסט טראומה. בשהייה בבית.","meeting":"in_person","target":"נכי ונכות צה״ל עם פוסט טראומה, במשבר, שזקוקים למסגרת זמנית","region":"חופית","cost":"ללא עלות","notes":"עד 10 אנשים, עד 3 חודשים, ואחר כך ליווי עד 3 חודשים. פנסיון מלא. אינו חלופת אשפוז, ולא מתאים לאובדנות פעילה, לפסיכוזה פעילה או לשימוש בחומרים. התחייבות מעובדת השיקום. מופעל על ידי שני בקהילה."}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Psychotherapy, and also psychiatric treatment, in a transitional home for post-traumatic stress. While staying at the home.","meeting":"in_person","target":"IDF disabled men and women with post-traumatic stress, in a crisis, who need a temporary setting","region":"Hofit","cost":"At no cost","notes":"Up to 10 people, up to 3 months, and then accompaniment for up to 3 months. Full board. It is not an alternative to hospitalization, and it is not suitable for active suicidality, active psychosis, or substance use. A commitment from the rehabilitation social worker. Operated by Sheni BaKehila."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/medical/mental-therapy/maavar_housing. סדר היום לא עולה לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (762, true, '762|||בית מאזן בקהילה — מניעת אשפוז', '762|||שהות קצרה בבית מאזן, כדי למנוע אשפוז. בשהייה בבית.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"שהות קצרה בבית מאזן, כדי למנוע אשפוז. בשהייה בבית.","meeting":"in_person","target":"נכי צה״ל במשבר נפשי. בתים ייעודיים למי שהוכר או קיבל הכרה עקרונית. בתים כלליים למי שעדיין בלי הכרה עקרונית","region":"רחובות, באר שבע, תל אביב, הרצליה, מטע, לוד, ירושלים, כפר יונה, חדרה, קיסריה, קריית אתא, כרמיאל, מגדל העמק, סוואעד חמירה, הרדוף, יבנה, אבן יהודה, בני דרור","cost":"ללא עלות","notes":"עד 3 חודשים, עד 12 אנשים, באישור הרופא המחוזי. לא מתאים לאובדנות פעילה, לפסיכוזה פעילה או לשימוש בחומרים. בתים ייעודיים: בית שחר ברחובות ובית יהב בבאר שבע. בתים מאזנים ובית בטוח בכרטיסים נפרדים."}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"A short stay in a balancing home, in order to prevent hospitalization. While staying at the home.","meeting":"in_person","target":"IDF disabled people in a mental crisis. Dedicated homes for a person who was recognized or received preliminary recognition. General homes for a person still without preliminary recognition","region":"Rehovot, Beer Sheva, Tel Aviv, Herzliya, Mata, Lod, Jerusalem, Kfar Yona, Hadera, Caesarea, Kiryat Ata, Karmiel, Migdal HaEmek, Suwaed Hamira, Harduf, Yavne, Even Yehuda, Bnei Dror","cost":"At no cost","notes":"Up to 3 months, up to 12 people, with approval from the district doctor. Not suitable for active suicidality, active psychosis, or substance use. Dedicated homes: Beit Shachar in Rehovot and Beit Yahav in Beer Sheva. Balancing homes and Bayit Batuach are on separate cards."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/medical/mental-therapy/balancing-house. הרחובות לא עולים לאזור. הניסוח אושר עם אצוות משרד הביטחון.'),
  (763, true, '763|||קבוצות טיפוליות לנכי צה״ל ולבני משפחה', '763|||טיפול קבוצתי לנכי צה״ל ולבני משפחה. במפגש.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"טיפול קבוצתי לנכי צה״ל ולבני משפחה. במפגש.","meeting":"in_person","target":"מי שהוכרו כנכי צה״ל, והורים, בני זוג וילדים","region":"כל הארץ","cost":"אגף השיקום","notes":"מפגש שבועי. חלק מהקבוצות משלבות פעילות בחוץ, מותאמת גם לנכות פיזית. הרישום במערכת הקבוצות."}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Group therapy for IDF disabled people and for family members. At a meeting.","meeting":"in_person","target":"People recognized as IDF disabled, and parents, spouses, and children","region":"Nationwide","cost":"The rehabilitation division","notes":"A weekly meeting. Some groups add outdoor activity, also adapted to a physical disability. Registration is in the groups system."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/rehabilitation/vocational/group-therapy. כתובות המייל של המחוזות לא עולות לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (764, true, '764|||חונכות אישית לשיקום בבית ובקהילה', '764|||חונכות אישית לשיקום בבית ובקהילה. בבית או בקהילה.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"חונכות אישית לשיקום בבית ובקהילה. בבית או בקהילה.","meeting":"in_person","target":"20% נכות לפחות על פגיעה נפשית או פגיעת ראש, או 100% ומעלה על כל פגיעה","region":"כל הארץ","cost":"אגף השיקום","notes":"פונים קודם לעובדת השיקום, גם אם אחר כך פונים לספק. רשימת הספקים בדף. זו חונכות של אגף השיקום, לא חונכות של סל השיקום."}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Personal mentoring for rehabilitation at home and in the community. At home or in the community.","meeting":"in_person","target":"At least 20% disability for a mental injury or a head injury, or 100% and above for any injury","region":"Nationwide","cost":"The rehabilitation division","notes":"Apply first to the rehabilitation social worker, even when contacting a supplier later. The supplier list is on the page. This is mentoring from the rehabilitation division, separate from rehabilitation-basket mentoring."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/rehabilitation/vocational/tutoring. טלפוני הספקים והשעות לא עולים לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (765, true, '765|||טיפולי רפואה משלימה באפליקציית Shikum.Me', '765|||רפואה משלימה ופעילות ספורט, באפליקציית Shikum.Me.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"רפואה משלימה ופעילות ספורט, באפליקציית Shikum.Me.","meeting":"","target":"20% נכות לפחות על פוסט טראומה, פגיעה נפשית או פגיעת ראש, או 10% אם ההכרה לפני 31.12.1995, או נכות מיוחדת 100%+","region":"כל הארץ","cost":"אגף השיקום","notes":"היתרה לא עוברת לשנה הבאה. בחירת המטפל באחריות הפונה. מי שקיבל טיפולים ב-2025 יכול להגיש קבלות בתקופת הסתגלות, וזה גורע מהיתרה באפליקציה.","phone":"074-7174830","phoneLabel":"מוקד","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Complementary medicine and sports activity, in the Shikum.Me app.","meeting":"","target":"At least 20% disability for post-traumatic stress, a mental injury, or a head injury, or 10% if recognition was before 31.12.1995, or special disability of 100% or more","region":"Nationwide","cost":"The rehabilitation division","notes":"The balance does not carry over to the next year. Choosing the practitioner is the responsibility of the person applying. A person who received treatments in 2025 can submit receipts during the adjustment period, and that reduces the balance in the app.","phone":"074-7174830","phoneLabel":"Call center","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/medical/treatment/alternative. 6,600 ש״ח ושעות המוקד לא עולים לכרטיס. הניסוח אושר עם אצוות משרד הביטחון.'),
  (766, true, '766|||טיפול נפשי לבני משפחה', '766|||טיפול נפשי לבני משפחה של מי שהוכר. אצל מכון שבהסדר.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"טיפול נפשי לבני משפחה של מי שהוכר. אצל מכון שבהסדר.","meeting":"","target":"הורים, בן או בת זוג, וילדים מגיל 7 עד 30","region":"כל הארץ","cost":"אגף השיקום","notes":"שעת טיפול בשבוע, פרטני, זוגי או משפחתי. מי שהחל בהחזר לפני 20.10.2026 יכול להמשיך אצל המטפל הקבוע. ילדים עד 18 יכולים לקבל במקום זה החזר על רפואה משלימה בקופת החולים. בהכרה עקרונית של פצועי חרבות ברזל: 12 מפגשים, ואחים מגיל 7 עד 18 רק במכון שבהסדר. לחייל בודד אפשר לבדוק זכאות לאדם משמעותי אחד.","email":"shikum_mokedtipulim@mod.gov.il","emailLabel":"אימייל","emailShowAddress":false,"email2":"","emailLabel2":"","emailShowAddress2":false,"email3":"","emailLabel3":"","emailShowAddress3":false}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Mental-health treatment for family members of a recognized person. At an institute in the arrangement.","meeting":"","target":"Parents, a spouse, and children from age 7 to 30","region":"Nationwide","cost":"The rehabilitation division","notes":"One treatment hour a week, individual, couples, or family. A person who started a refund before 20.10.2026 can continue with the regular therapist. Children up to 18 can instead receive a refund for complementary medicine through the health fund. In preliminary recognition for Iron Swords wounded: 12 sessions, and siblings from age 7 to 18 only at an institute in the arrangement. A lone soldier can ask about eligibility for one significant person.","email":"shikum_mokedtipulim@mod.gov.il","emailLabel":"Email","email2":"","emailLabel2":"","email3":"","emailLabel3":""}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/family/support/therapy. 384 ש״ח לא עולה לכרטיס. המסלול העיקרי הוא מכון שבהסדר. הניסוח אושר עם אצוות משרד הביטחון.'),
  (767, true, '767|||טיפול בתפקוד האינטימי', '767|||טיפול בתפקוד האינטימי. במרפאה בבית חולים.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"טיפול בתפקוד האינטימי. במרפאה בבית חולים.","meeting":"in_person","target":"פגיעה מוכרת בתפקוד המיני, או 30% נכות נפשית או פוסט טראומה לצמיתות או לשלוש שנים, או 40% על פגיעת ראש","region":"כל הארץ","cost":"אגף השיקום","notes":"אצל מטפלים מוסמכים, בלי עירום ובלי מגע אינטימי. מתחילים בהתחייבות דרך האזור האישי או מרפאת המחוז. ויאגרה או סיאליס: עד 8 כדורים בחודש דרך האגף."}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Treatment for intimate function. At a hospital clinic.","meeting":"in_person","target":"A recognized injury to sexual function, or 30% mental or post-traumatic disability permanently or for three years, or 40% for a head injury","region":"Nationwide","cost":"The rehabilitation division","notes":"With certified therapists, with no nudity and no intimate touch. It starts with a commitment through the personal area or the district clinic. Viagra or Cialis: up to 8 tablets a month through the division."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/medical/treatment/intimacy-therapy. הניסוח אושר עם אצוות משרד הביטחון.'),
  (768, true, '768|||הבראה למתמודדים עם פגיעה נפשית', '768|||השלמת ימי הבראה למי שנקבעה לו נכות נפשית. במלון שבהסדר.', '{"specialty":"","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"השלמת ימי הבראה למי שנקבעה לו נכות נפשית. במלון שבהסדר.","meeting":"","target":"מי שנקבעה לו נכות נפשית","region":"כל הארץ","cost":"אגף השיקום","notes":"אי אפשר להמיר את התוספת לכסף. מספר הימים תלוי באחוז הנכות הנפשית ובאחוז הנכות הכוללת, והפירוט בדף."}'::jsonb, '{"specialty":"","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Extra convalescence days for a person with a mental disability. At a hotel in the arrangement.","meeting":"","target":"A person for whom a mental disability was set","region":"Nationwide","cost":"The rehabilitation division","notes":"The extra days cannot be converted to money. The number of days depends on the mental-disability percentage and the total-disability percentage, and the details are on the page."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/medical/relaxation/mental. מספר הימים תלוי גם באחוז הנכות הכוללת, והטבלה נשארת בדף. הניסוח אושר עם אצוות משרד הביטחון.'),
  (769, true, '769|||טיפולים חדשניים להקלה בפוסט טראומה', '769|||טיפול ב-Prism ובגרייה מגנטית עמוקה, כשטיפולים מקובלים לא הספיקו. במרפאה.', '{"specialty":"פוסט טראומה","approaches":"","org":"אגף השיקום, משרד הבטחון","svc":"טיפול ב-Prism ובגרייה מגנטית עמוקה, כשטיפולים מקובלים לא הספיקו. במרפאה.","meeting":"in_person","target":"מי שמטופל באגף על פוסט טראומה","region":"כל הארץ","cost":"אגף השיקום","notes":"ההתחייבות אחרי המלצה מרופא מומחה. Prism הוא 15 מפגשים. Deep TMS הוא 20 עד 30 מפגשים. Prism וגרייה מגנטית בכרטיסים נפרדים."}'::jsonb, '{"specialty":"Post-traumatic stress","approaches":"","org":"Rehabilitation Division, Ministry of Defense","svc":"Treatment with Prism and deep magnetic stimulation, when ordinary treatments were not enough. At the clinic.","meeting":"in_person","target":"A person treated by the division for post-traumatic stress","region":"Nationwide","cost":"The rehabilitation division","notes":"The commitment comes after a recommendation from a specialist. Prism is 15 sessions. Deep TMS is 20 to 30 sessions. Prism and magnetic stimulation are on separate cards."}'::jsonb, '25.11.2026: נבדק מול https://shikum.mod.gov.il/medical/treatment/ptsd. הניסוח אושר עם אצוות משרד הביטחון.');

UPDATE site_audit_entries s
SET card_keys = (
  SELECT COALESCE(array_agg(
    COALESCE((SELECT w.new_key FROM mod_wording w WHERE w.old_key = k), k)
    ORDER BY ord
  ), '{}')
  FROM unnest(s.card_keys) WITH ORDINALITY AS u(k, ord)
)
WHERE EXISTS (
  SELECT 1
  FROM unnest(s.card_keys) k
  JOIN mod_wording w ON w.old_key = k
);

UPDATE directory_card_edits c
SET card_key = w.new_key,
    public_fields = COALESCE(c.public_fields, '{}'::jsonb) || w.fields,
    translations = jsonb_set(
      COALESCE(c.translations, '{}'::jsonb),
      '{en}',
      COALESCE(c.translations->'en', '{}'::jsonb) || w.en,
      true
    ),
    eligibility = jsonb_set(
      COALESCE(c.eligibility, '{}'::jsonb),
      '{internal_notes}',
      to_jsonb(
        CASE
          WHEN COALESCE(c.eligibility->>'internal_notes', '') = '' THEN w.note
          ELSE rtrim(c.eligibility->>'internal_notes') || E'\n\n' || w.note
        END
      ),
      true
    ),
    public_edited_at = now(),
    updated_at = now()
FROM mod_wording w
WHERE c.card_key = w.old_key
   OR (
     w.unique_row
     AND c.row_id = w.row_id
     AND (SELECT count(*) FROM directory_card_edits d WHERE d.row_id = w.row_id) = 1
   );

UPDATE directory_entries e
SET display_name = c.public_fields->>'org',
    description = c.public_fields->>'svc'
FROM directory_card_edits c
JOIN mod_wording w ON w.new_key = c.card_key
WHERE e.entry_id = c.entry_id;

